mapper.select:
SELECT COUNT(*)
FROM ${table} t
JOIN tl_documents d ON d.doc_id = t.original_doc_id
WHERE d.uploader_user_id = #{userId}
  AND t.original_doc_id = #{docId}

  AND t.target_language = #{targetLang}


  AND t.provider = #{provider}

SELECT 
FROM ${table} t
JOIN tl_documents d ON d.doc_id = t.original_doc_id
WHERE d.uploader_user_id = #{userId}
  AND t.original_doc_id = #{docId}

  AND t.target_language = #{targetLang}


  AND t.provider = #{provider}

ORDER BY COALESCE(t.translated_at, t.created_at) DESC, t.request_id DESC
LIMIT #{limit} OFFSET #{offset}

